def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            comps.append((r0, r1, c0, c1))

    best = None
    for i in range(len(comps)):
        for j in range(i + 1, len(comps)):
            a, b = comps[i], comps[j]
            if (a[1] - a[0], a[3] - a[2]) != (b[1] - b[0], b[3] - b[2]):
                continue
            rh, cw = a[1] - a[0] + 1, a[3] - a[2] + 1
            diffs = []
            matches = 0
            for y in range(rh):
                for x in range(cw):
                    va = grid[a[0] + y][a[2] + x]
                    vb = grid[b[0] + y][b[2] + x]
                    if va != vb:
                        diffs.append((y, x))
                    else:
                        matches += 1
            if not diffs:
                continue
            score = (matches / (rh * cw), rh * cw)
            if best is None or score > best[0]:
                best = (score, rh, cw, diffs)

    if best is None:
        return [[0]]

    _, rh, cw, diffs = best
    first = min(y for y, x in diffs)
    last = max(y for y, x in diffs)
    out = [[0] * cw for _ in range(last - first + 1)]
    for y, x in diffs:
        out[y - first][x] = 8
    return out
